const basic_LLM_Chain_Analyze_Incident = node({
  type: '@n8n/n8n-nodes-langchain.chainLlm',
  version: 1.9,
  config: { name: 'Basic LLM Chain - Analyze Incident', parameters: { promptType: 'define', text: expr('<instructions>\n<goal>Explain one failed n8n execution so that the owner can act in under a minute.</goal>\n<rules>\n1. Base the cause only on the node name, the error message and the stack given in the inputs.\n2. Answer in French, in plain words, one sentence per field.\n3. replay is "yes" for a temporary failure (429, timeout, 5xx, network), "no" for a credential, a permission or a bad data problem, "uncertain" otherwise.\n4. If the information is not enough, say it in probableCause and give the check that would settle it in nextStep.\n</rules>\n<examples>\n<example>\n<input>Node: Gemini Chat - Main Model. Message: 429 quota exceeded for this model.</input>\n<output>{"probableCause":"Quota Gemini dépassé (erreur 429).","nextStep":"Attendre une minute puis rejouer l\'exécution, ou réduire le nombre d\'analyses du mois.","replay":"yes"}</output>\n</example>\n<example>\n<input>Node: Notion - Create Diagnostic Page. Message: Could not find database with ID.</input>\n<output>{"probableCause":"La base Analyses n\'est plus partagée avec l\'intégration Notion.","nextStep":"Partager la base avec l\'intégration, puis rejouer la livraison avec le déclencheur manuel.","replay":"no"}</output>\n</example>\n<example>\n<input>Node: GitHub - Get Repository. Message: The resource you are requesting could not be found.</input>\n<output>{"probableCause":"Le dépôt n\'existe pas ou il est privé : l\'URL saisie est probablement fausse.","nextStep":"Vérifier l\'URL dans le formulaire puis renvoyer la demande.","replay":"no"}</output>\n</example>\n<example>\n<input>Node: Code - Validate And Finalize Diagnostic. Message: Cannot read properties of undefined.</input>\n<output>{"probableCause":"Un champ attendu manque dans la réponse de l\'IA ou dans les preuves GitHub, la cause exacte n\'est pas visible ici.","nextStep":"Ouvrir l\'exécution et regarder la sortie du nœud précédent pour voir quel champ est vide.","replay":"uncertain"}</output>\n</example>\n</examples>\n<output_format>One JSON object with the keys probableCause, nextStep and replay (yes, no or uncertain). No text around it.</output_format>\n</instructions>\n<inputs>\n<workflow>{{ $json.workflowName }}</workflow>\n<node>{{ $json.nodeName }}</node>\n<message>{{ $json.errorMessage }}</message>\n<stack>{{ $json.stack }}</stack>\n</inputs>\n'), messages: { messageValues: [{ message: 'You are the n8n incident assistant of Mathieu, a French freelancer who runs n8n automations for clients. You read one failed execution and tell him, in French, the probable cause and the next concrete step. You never invent a cause: when the error is not enough to decide, you say so and name the single check that would settle it. You never repeat secrets, tokens or personal data found in an error message.\n' }] }, hasOutputParser: true, batching: {} }, position: [960, 9000], notes: 'Small model, short answer: cause, next step and whether a replay is worth it. If the AI is down the alert is still sent.', notesInFlow: true, onError: 'continueRegularOutput', subnodes: { model: gemini_Chat_Incident_Model, outputParser: output_Parser_Incident_Analysis } }
});

